import{at as e,it as t,n,tt as r,vt as i}from"./chunks/framework.DbV_8hbX.js";import"./chunks/assets.ByxXdwmG.js";var a=JSON.parse(`{"title":"What is JevSense?","description":"","frontmatter":{},"headers":[],"relativePath":"en/introduction/overview.md","filePath":"en/introduction/overview.md","lastUpdated":1794405696000}`),o={name:`en/introduction/overview.md`};function s(n,a,o,s,c,l){return i(),t(`div`,null,[...a[0]||=[e(`<h1 id="what-is-jevsense" tabindex="-1">What is JevSense? <a class="header-anchor" href="#what-is-jevsense" aria-label="Permalink to “What is JevSense?”">​</a></h1><p>JevSense is a web personalization platform. It judges a visitor&#39;s interests and state from how they browse, then shows a prepared message at the right moment. You run it in your own Cloudflare or Node.js environment.</p><div class="tip custom-block"><p class="custom-block-title">About the admin console language</p><p>The admin console is currently available in Japanese only. In this Help, screen labels appear as an English translation followed by the original Japanese label in 「 」, for example &quot;Help and manual (「ヘルプ・マニュアル」)&quot;.</p></div><h2 id="where-it-fits" tabindex="-1">Where it fits <a class="header-anchor" href="#where-it-fits" aria-label="Permalink to “Where it fits”">​</a></h2><table tabindex="0"><thead><tr><th>Site type</th><th>Example</th></tr></thead><tbody><tr><td>E-commerce</td><td>Point people interested in functional apparel to a feature page</td></tr><tr><td>B2B</td><td>Introduce an onboarding guide to people interested in adoption and operations</td></tr><tr><td>Media</td><td>Suggest related articles to people who keep reading about a specific topic</td></tr><tr><td>Recruiting</td><td>Invite people interested in your development environment to an engineering event</td></tr><tr><td>Education</td><td>Suggest an information session to people interested in how to study</td></tr><tr><td>Booking</td><td>Offer a consultation desk to people considering a plan</td></tr></tbody></table><p>The text, images, links and JavaScript to display are prepared in advance by an administrator.</p><h2 id="how-decisions-are-made" tabindex="-1">How decisions are made <a class="header-anchor" href="#how-decisions-are-made" aria-label="Permalink to “How decisions are made”">​</a></h2><p>In the admin console you set the audience conditions and the message to show, and register the content to display. JevSense does not ask Jev on every measurement. Measuring in the browser, asking the API for a decision and asking Jev each have their own conditions for moving on to the next step.</p>`,8),r(`div`,{class:`workflow-scroll`,role:`region`,"aria-label":`JevSense system workflow diagram. It scrolls horizontally.`,tabindex:`0`},[r(`p`,null,[r(`img`,{src:`/jev-personalization/images/system-workflow.svg`,alt:`JevSense processing flow, including the branch that only keeps measuring, the branch where the API holds without sending to Jev, and the branch where display is held even after Jev's judgment`,width:`1120`,height:`1200`})])],-1),e(`<p><a href="/jev-personalization/images/system-workflow.svg">Open the diagram in full size</a>. On a smartphone you can scroll the diagram horizontally. The diagram&#39;s labels are in Japanese.</p><ol><li>After consent, the shared SDK observes browsing order, display time and page information.</li><li>Once, when a page opens, it sends the current and entry pages and the past valid views to your own API. Reaching the minimum viewing time and changes in actions or state are stored in the browser and used for the initial decision on the next page.</li><li>The API checks things such as valid views and target campaigns. Only when the conditions are met does it send Jev the state and independent Yes/No questions.</li><li>When the judgment score comes back, code checks the threshold, AND/OR and display constraints.</li><li>Only when display is allowed does it return the registered content, and the SDK shows it on the page.</li></ol><p>The flow can also end earlier in one of these ways.</p><ul><li><strong>Measure only</strong>: time passing or actions after the initial decision only update the record in the browser.</li><li><strong>Held at the API</strong>: if viewing time is too short or there is no target campaign, nothing is sent to Jev. A missing key or a cost limit also stops the request.</li><li><strong>Held after asking Jev</strong>: nothing is displayed if the score does not reach the threshold, the judgment is uncertain, or there is a communication or response problem.</li></ul><p>URL and Jev conditions are combined by connecting nodes with AND/OR. If the URL alone settles the result, the request to Jev is skipped even for a campaign that contains Jev conditions. Only the questions that need inference are bundled into one request, and the remaining conditions are evaluated from the answer. See <a href="./../guides/campaigns">Create campaigns</a> for details.</p><h2 id="how-it-differs-from-generative-ai" tabindex="-1">How it differs from generative AI <a class="header-anchor" href="#how-it-differs-from-generative-ai" aria-label="Permalink to “How it differs from generative AI”">​</a></h2><p>Jev is used to judge the audience. It is not used to generate text, images or HTML. The input assistance in the admin console also just fits the sentence you typed into a fixed question template.</p><p>The judgment score is evidence for &quot;does this interest or state apply?&quot;. It does not guarantee purchase rate, campaign effect or future behavior.</p><h2 id="where-to-start-by-role" tabindex="-1">Where to start, by role <a class="header-anchor" href="#where-to-start-by-role" aria-label="Permalink to “Where to start, by role”">​</a></h2><p><strong>If you build campaigns</strong>, accept an invitation from an administrator, register your <a href="./../guides/accounts">account</a> and <a href="./../guides/campaigns">create campaigns</a>. You don&#39;t need to install a development environment.</p><p><strong>If you install it</strong>, set up <a href="./../getting-started/cloudflare">Cloudflare</a> or <a href="./../getting-started/node">Node.js</a>, then place the <a href="./../integration/sdk">SDK tag</a>.</p><p><strong>If you operate it</strong>, read <a href="./../operations/security">permissions and secrets</a> and <a href="./../operations/maintenance">updates and recovery</a>.</p><h2 id="data-that-is-stored" tabindex="-1">Data that is stored <a class="header-anchor" href="#data-that-is-stored" aria-label="Permalink to “Data that is stored”">​</a></h2><p>The visitor&#39;s history and the displayed state are kept in the browser. No visitor ID, visitor session or behavior-history database is added on the server.</p><p>An administrator&#39;s account, passkey public key, memberships and campaign settings are stored in the admin database. That does not mean nothing is sent externally, so please also read <a href="./../integration/data">data collected and sent</a>.</p>`,15)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};